function loadRoutes(terminal) {
    if (!terminal || terminal === "") {
        routesContainer.innerHTML = '<p class="no-routes-msg">Selecciona una terminal para ver las rutas</p>';
        routeCount.textContent = '0 routes';
        return;
    }

    // Limpieza de estado
    routesContainer.innerHTML = '';
    selectedRoute = null; 
    startTrackingBtn.disabled = true;
    clearMap(); 

    const routes = terminalRoutes[terminal] || [];
    routeCount.textContent = `${routes.length} routes`;

    routes.forEach((route) => {
        const routeSquare = document.createElement('div');
        routeSquare.className = 'route-square';
        
        // Extraemos solo el número (ej: de "OCC-201" a "201")
        // Si prefieres el ID completo, usa solo: route.id
        const routeNumber = route.id.substring(route.id.indexOf('-') + 1);
        routeSquare.textContent = routeNumber;

        // Evento de selección
        routeSquare.addEventListener('click', () => {
            document.querySelectorAll('.route-square').forEach(item => {
                item.classList.remove('active');
            });
            
            routeSquare.classList.add('active');
            selectedRoute = route;
            validateTracking();
        });

        routesContainer.appendChild(routeSquare);
    });
}

// =====================================================
// VALIDAR BOTÓN (CORREGIDO)
// =====================================================
function validateTracking() {
    // El select siempre tiene valor, la única condición real es selectedRoute
    if (selectedRoute) {
        startTrackingBtn.disabled = false;
    } else {
        startTrackingBtn.disabled = true;
    }
}

    // =====================================================
    // LIMPIAR MAPA
    // =====================================================

    function clearMap() {

    if (rutaLine && map.hasLayer(rutaLine)) {
        map.removeLayer(rutaLine);
    }

    if (busMarker && map.hasLayer(busMarker)) {
        map.removeLayer(busMarker);
    }

    if (destMarker && map.hasLayer(destMarker)) {
        map.removeLayer(destMarker);
    }
}

    // =====================================================
    // DIBUJAR TRACKING
    // =====================================================

    // --- SUSTITUYE TU FUNCIÓN renderTracking POR ESTA ---
function renderTracking() {
    if (!selectedRoute) return;

    clearMap();

    const routeCoords = selectedRoute.coords;

    // 1. Dibujar la línea (el camino)
    rutaLine = L.polyline(routeCoords, {
        color: colorPicker.value,
        weight: 5,
        opacity: 0.8,
        dashArray: '8, 12'
    }).addTo(map);

    // 2. Marcador de Destino (Fijo)
    destMarker = L.marker(
        routeCoords[routeCoords.length - 1],
        { icon: destIcon }
    ).addTo(map);

    // 3. Marcador del Bus (Inicializado en el primer punto)
    busMarker = L.marker(routeCoords[0], { icon: busIcon }).addTo(map);

    // 4. Ajustar vista del mapa
    map.fitBounds(rutaLine.getBounds(), { padding: [40, 40] });

    // 5. ¡INICIAR ANIMACIÓN!
    // Pasamos el marcador, el arreglo de coordenadas y la velocidad (ms)
    animateBus(busMarker, routeCoords, 0, 1000); 
}

/**
 * Mueve el bus suavemente de un punto a otro
 * @param {L.Marker} marker - El objeto del bus
 * @param {Array} coords - El array de [lat, lng]
 * @param {number} index - El punto actual en el camino
 * @param {number} speed - Tiempo entre puntos en milisegundos
 */
function animateBus(marker, coords, index, speed) {
    if (index >= coords.length - 1) {
        console.log("Llegada a destino");
        return; // Detener cuando llegue al final
    }

    // Punto origen y punto destino de este tramo
    const start = coords[index];
    const end = coords[index + 1];

    // Actualizar posición del marcador
    marker.setLatLng(end);

    // Esperar y saltar al siguiente punto
    setTimeout(() => {
        animateBus(marker, coords, index + 1, speed);
    }, speed);
}

    // =====================================================
    // EVENTO CAMBIO TERMINAL
    // =====================================================

    terminalSelect.addEventListener('change', () => {

        loadRoutes(terminalSelect.value);

    });

    // =====================================================
// EVENTO BOTÓN TRACKING (CORREGIDO)
// =====================================================
startTrackingBtn.addEventListener('click', () => {
    // 1. Validar que haya una ruta seleccionada
    if (!selectedRoute) return;

    // 2. Seleccionamos los elementos de la UI
    const statusDot = document.getElementById('statusDot');
    const statusText = document.getElementById('statusText');
    const statusPill = document.getElementById('statusPillContainer');

    // 3. Cambiar visualmente el indicador a "Live"
    statusDot.classList.add('active'); // Activa el color verde y la animación CSS
    statusText.textContent = 'Live Tracking';
    
    // Cambiamos el borde del pill a verde para que haga juego
    if (statusPill) {
        statusPill.style.borderColor = '#2ecc71';
    }

    // 4. Ejecutar el dibujo en el mapa
    renderTracking();

    console.log("Tracking iniciado correctamente para:", selectedRoute.nombre);
});

    // =====================================================
    // CAMBIO DE COLOR EN TIEMPO REAL
    // =====================================================

    colorPicker.addEventListener('input', () => {

        // Actualizar colores visuales de rutas
        document.querySelectorAll('.route-marker')
            .forEach(marker => {
                marker.style.background = colorPicker.value;
            });

        // Redibujar si ya hay ruta activa
        if (selectedRoute && rutaLine) {
            renderTracking();
        }
    });

    // =====================================================
    // RELOJ
    // =====================================================

    function updateClock() {

        document.getElementById('liveClock').innerText =
            new Date().toLocaleTimeString([], {
                hour: '2-digit',
                minute: '2-digit'
            });
    }

    setInterval(updateClock, 1000);

    updateClock();

    // =====================================================
    // INICIALIZACIÓN
    // =====================================================

    console.log("SCRIPT FUNCIONANDO");


   // Eliminamos la carga automática. 
// Ahora el contenedor mostrará un mensaje inicial o estará vacío.
routesContainer.innerHTML = '<p class="no-routes-msg">Selecciona una terminal para ver las rutas</p>';
routeCount.textContent = '0 routes';

$(document).ready(function() {
    $('#terminalSelect').select2({
        placeholder: "Buscar terminal...",
        allowClear: false,
        width: '100%' // Asegura que use todo el ancho del sidebar
    });
});

